def write_batch(batch, name):
    for r in batch:
        p = os.path.join(BASE, r["case_id"] + ".json")
        assert not os.path.exists(p), f"exists, refuse overwrite: {p}"
        with open(p, "w", encoding="utf-8") as f:
            json.dump(r, f, ensure_ascii=False, indent=1)
    # verify
    for r in batch:
        p = os.path.join(BASE, r["case_id"] + ".json")
        d = json.load(open(p, encoding="utf-8"))
        assert d["case_id"] == r["case_id"]
        assert set(["case_id","prediction_text","basis","confidence","trigger"]) <= set(d)
        assert 0 <= d["confidence"] <= 1
        assert set(d["trigger"]) == {"changed_main","reserve_used","disputed","reason"}
        assert all(isinstance(d["trigger"][k], bool) for k in ["changed_main","reserve_used","disputed"])
    print(name, "written+verified", len(batch))

write_batch(B09, "B09")
write_batch(B10, "B10")
for nm, b in [("B09", B09), ("B10", B10)]:
    cm = sum(r["trigger"]["changed_main"] for r in b)
    ru = sum(r["trigger"]["reserve_used"] for r in b)
    di = sum(r["trigger"]["disputed"] for r in b)
    print(nm, "trigger counts changed_main/reserve_used/disputed =", cm, ru, di)
print("TOTAL", len(B09)+len(B10))
